import React, { useState, useEffect } from 'react';

export default function App() {
  const [crowd, setCrowd] = useState(null);
  const [amenities, setAmenities] = useState([]);

  useEffect(() => {
    fetch("http://localhost:8000/api/crowd-status")
      .then(res => res.json())
      .then(data => setCrowd(data))
      .catch(err => console.error("Crowd fetch error:", err));

    fetch("http://localhost:8000/api/amenities")
      .then(res => res.json())
      .then(data => setAmenities(data))
      .catch(err => console.error("Amenities fetch error:", err));
  }, []);

  return (
    <div style={{ fontFamily: 'sans-serif', padding: '24px', maxWidth: '900px', margin: 'auto' }}>
      <header style={{ borderBottom: '2px solid #ea580c', paddingBottom: '12px', marginBottom: '20px' }}>
        <h1 style={{ color: '#ea580c', margin: 0 }}>🚩 Rahbar (रहबर)</h1>
        <p style={{ margin: '4px 0', color: '#555' }}>Smart Pilgrim Guidance & Crowd Re-direction Platform</p>
      </header>

      {/* Live Crowd & Guidance Card */}
      {crowd && (
        <div style={{ background: '#fff7ed', border: '1px solid #fdba74', padding: '16px', borderRadius: '8px', marginBottom: '24px' }}>
          <h2 style={{ color: '#c2410c', marginTop: 0 }}>Live Shrine Status: {crowd.status} ({crowd.capacity_percentage}% Full)</h2>
          <p><strong>Current Zone:</strong> {crowd.location}</p>
          <p><strong>Expected Wait Time:</strong> {crowd.estimated_wait_time}</p>
          <div style={{ background: '#ffedd5', padding: '12px', borderRadius: '6px' }}>
            <strong>💡 Rahbar Recommendation:</strong> {crowd.redirection_advice}
          </div>
        </div>
      )}

      {/* Pilgrim Amenities & Safe Spots */}
      <h2>Pilgrim Services & Essentials</h2>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: '16px' }}>
        {amenities.map(item => (
          <div key={item.id} style={{ border: '1px solid #ddd', padding: '14px', borderRadius: '8px', background: '#fafafa' }}>
            <span style={{ fontSize: '11px', background: '#e0e7ff', color: '#3730a3', padding: '3px 8px', borderRadius: '12px', fontWeight: 'bold' }}>
              {item.category}
            </span>
            <h3 style={{ margin: '10px 0 6px 0', fontSize: '16px' }}>{item.name}</h3>
            <p style={{ margin: '4px 0', fontSize: '13px', color: '#555' }}>🕒 {item.timing}</p>
            <p style={{ margin: '4px 0', fontSize: '13px', color: '#16a34a' }}>✔ {item.status}</p>
            <p style={{ margin: '6px 0 0 0', fontSize: '13px' }}>📞 <strong>{item.contact}</strong></p>
          </div>
        ))}
      </div>
    </div>
  );
}
